const norm=s=>String(s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g," ").trim();
const slug=s=>norm(s).replace(/\s+/g,"-");
function findExisting(old,name,used){
  const target=norm(name);
  let idx=old.findIndex((p,i)=>!used.has(i)&&norm(p&&p.name)===target);
  if(idx>=0)return idx;
  const last=target.split(" ").filter(Boolean).pop()||"";
  if(last.length>=5){
    const hits=[];
    old.forEach((p,i)=>{
      if(used.has(i))return;
      const pn=norm(p&&p.name);
      const plast=pn.split(" ").filter(Boolean).pop()||"";
      if(plast===last)hits.push(i);
    });
    if(hits.length===1)return hits[0];
  }
  return -1;
}
